package cn.jingyu.deepseek;
import org.json.*;import java.util.*;

/** Bounded tool surface. Automatic tool selection, official endpoints only. */
public final class AgentTools {
 static JSONObject property(String type,String description)throws JSONException{return new JSONObject().put("type",type).put("description",description);}
 static JSONObject function(String name,String description,JSONObject properties,String...required)throws JSONException{return new JSONObject().put("type","function").put("function",new JSONObject().put("name",name).put("description",description).put("parameters",new JSONObject().put("type","object").put("properties",properties).put("required",new JSONArray(Arrays.asList(required)))));}
 public static JSONArray definitions(boolean artifacts,boolean memory,boolean recall)throws JSONException {JSONArray result=new JSONArray(),all=definitions();for(int i=0;i<all.length();i++){JSONObject tool=all.getJSONObject(i);String name=tool.getJSONObject("function").getString("name");if(name.equals("create_file")&&!artifacts)continue;if((name.equals("remember_memory")||name.equals("forget_memory")||name.equals("search_memory"))&&!memory)continue;if(name.equals("recall_conversation")&&!recall)continue;result.put(tool);}return result;}
 public static JSONArray definitions()throws JSONException {JSONArray tools=new JSONArray();tools.put(function("web_search","搜索互联网获取最新或需核实的信息，返回带来源URL和发布日期的网页资料。按需调用，不需要每条消息都搜索。",new JSONObject().put("query",property("string","1至128个Unicode字符的明确检索词，可包含 site: 或 after: 日期限定")),"query"));tools.put(function("web_fetch","读取用户给出的或搜索结果中的公开HTTP/HTTPS网页。返回Markdown正文，网页可能不可访问。",new JSONObject().put("url",property("string","公开网页完整URL")),"url"));tools.put(function("create_file","调用手机内置的文档引擎创建真实文件；不是代码执行。支持高质量Word/PDF、Excel数据表、Markdown/TXT/CSV；不支持PPT或HTML。先核对用户要求，提供完整内容，成功后显示文件卡片。",new JSONObject().put("format",property("string","目标格式").put("enum",new JSONArray(Arrays.asList(ArtifactFiles.FORMATS)))).put("name",property("string","具体文件名，不含路径，不直接复制用户指令")).put("title",property("string","成品标题，与正文一级标题一致")).put("style",property("string","固定版式模板").put("enum",new JSONArray().put("report").put("study").put("formal").put("plain"))).put("content",property("string","Word/PDF/文本的完整Markdown正文，不能只给大纲或HTML；公式用LaTeX" )).put("rows",new JSONObject().put("type","array").put("description","Excel/CSV严格矩形二维数据，首行为带单位的列名，数值使用JSON数字").put("items",new JSONObject().put("type","array").put("items",new JSONObject().put("anyOf",new JSONArray().put(new JSONObject().put("type","string")).put(new JSONObject().put("type","number")))))),"format","name"));JSONObject parameters=tools.getJSONObject(2).getJSONObject("function").getJSONObject("parameters");JSONObject properties=parameters.getJSONObject("properties");properties.put("layout",new JSONObject("{\"type\":\"object\",\"description\":\"Word/PDF页面布局；无需手写XML\",\"properties\":{\"orientation\":{\"type\":\"string\",\"enum\":[\"portrait\",\"landscape\"]},\"fontSize\":{\"type\":\"number\",\"minimum\":10,\"maximum\":14},\"subtitle\":{\"type\":\"string\"},\"pageNumbers\":{\"type\":\"boolean\"},\"toc\":{\"type\":\"boolean\"}}}"));
JSONObject sheetProps=new JSONObject().put("name",property("string","工作表名")).put("rows",properties.getJSONObject("rows")).put("columnFormats",new JSONObject().put("type","array").put("items",property("string","逐列格式").put("enum",new JSONArray().put("auto").put("text").put("number").put("integer").put("percent")))).put("chart",new JSONObject("{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"string\",\"enum\":[\"bar\",\"line\"]},\"title\":{\"type\":\"string\"},\"categoryColumn\":{\"type\":\"integer\",\"minimum\":0},\"valueColumn\":{\"type\":\"integer\",\"minimum\":0}},\"required\":[\"type\",\"categoryColumn\",\"valueColumn\"]}"));properties.put("sheets",new JSONObject().put("type","array").put("description","XLSX多工作表，1至12张；每表矩形rows，可选原生柱状/折线图").put("items",new JSONObject().put("type","object").put("properties",sheetProps).put("required",new JSONArray().put("name").put("rows"))));properties.put("columnFormats",sheetProps.getJSONObject("columnFormats"));properties.put("chart",sheetProps.getJSONObject("chart"));
tools.put(function("calculate","本地可靠计算：四则、幂、sqrt/sin/cos/tan/asin/acos/atan/ln/log10/exp/abs，pi/e；三角函数为弧度。也可统计数值数组的总和、均值、中位数、标准差；不执行代码。",new JSONObject().put("expression",property("string","例如100/(2*sqrt(100))；^为乘方")).put("values",new JSONObject().put("type","array").put("items",property("number","统计数值")))));
JSONArray memory=MemoryTools.definitions();for(int i=0;i<memory.length();i++)tools.put(memory.getJSONObject(i));return tools;}
 public static String system(){return PromptPolicy.system();}
 public static String cleanJSON(String raw){String value=raw.trim();if(value.startsWith("```")){int n=value.indexOf('\n');if(n>=0)value=value.substring(n+1);if(value.endsWith("```"))value=value.substring(0,value.length()-3);}return value.trim();}
}
